-- SQLite twin of database/schema.sql, used only by the automated tests.
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, email_verified INTEGER NOT NULL DEFAULT 0, verification_hash TEXT, reset_hash TEXT, reset_expires TEXT, bio TEXT, xp INTEGER NOT NULL DEFAULT 0, voting_streak INTEGER NOT NULL DEFAULT 0, votes_cast INTEGER NOT NULL DEFAULT 0, last_vote_date TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pets (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT NOT NULL, breed TEXT, photo_url TEXT NOT NULL, story TEXT, personality_tags TEXT, total_score INTEGER NOT NULL DEFAULT 0, vote_count INTEGER NOT NULL DEFAULT 0, bayesian_score REAL NOT NULL DEFAULT 0, report_count INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, owner_ip TEXT, owner_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pet_of_the_day (id INTEGER PRIMARY KEY AUTOINCREMENT, pet_id INTEGER NOT NULL, "date" TEXT NOT NULL UNIQUE);
CREATE TABLE votes (id INTEGER PRIMARY KEY AUTOINCREMENT, pet_id INTEGER NOT NULL, voter_ip TEXT NOT NULL, score INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (pet_id, voter_ip));
CREATE TABLE comments (id INTEGER PRIMARY KEY AUTOINCREMENT, pet_id INTEGER NOT NULL, text TEXT NOT NULL, commenter_ip TEXT, user_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE comment_likes (id INTEGER PRIMARY KEY AUTOINCREMENT, comment_id INTEGER NOT NULL, voter_ip TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (comment_id, voter_ip));
CREATE TABLE comment_reactions (id INTEGER PRIMARY KEY AUTOINCREMENT, comment_id INTEGER NOT NULL, voter_ip TEXT NOT NULL, emoji TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (comment_id, voter_ip, emoji));
CREATE TABLE achievements (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, code TEXT NOT NULL, unlocked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (user_id, code));
CREATE TABLE reports (id INTEGER PRIMARY KEY AUTOINCREMENT, target_type TEXT NOT NULL, target_id INTEGER NOT NULL, reporter_ip TEXT NOT NULL, reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (target_type, target_id, reporter_ip));
CREATE TABLE sessions (id TEXT PRIMARY KEY, data TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE rate_limits (k TEXT PRIMARY KEY, window_start INTEGER NOT NULL, hits INTEGER NOT NULL DEFAULT 1);
